package com.smart.agent.tool.progress;
import java.time.LocalDate;import java.util.Set;
public record ProjectProgressQueryInput(String projectId,String projectName,String mode,String dateField,String startDate,String endDate,Integer page,Integer pageSize){public ProjectProgressQueryInput{mode=mode==null?"detail":mode;page=page==null?1:page;pageSize=pageSize==null?20:pageSize;if(page<1||pageSize<1||pageSize>100)throw new IllegalArgumentException("Invalid pagination");if(projectId!=null&&projectId.isBlank())throw new IllegalArgumentException("Invalid project reference");if(!Set.of("summary","detail","tasks").contains(mode))throw new IllegalArgumentException("Unsupported mode");if(dateField!=null&&!dateField.equals("projectCreateDate"))throw new IllegalArgumentException("Unsupported date field");if(startDate!=null||endDate!=null){if(!"projectCreateDate".equals(dateField)||startDate==null||endDate==null)throw new IllegalArgumentException("Confirm date field and both dates");if(LocalDate.parse(startDate).isAfter(LocalDate.parse(endDate)))throw new IllegalArgumentException("Reversed date range");}}}
